  let starLv = 'all';

  const BY_ID = {};
  ACTIONS.forEach((a) => { BY_ID[a.id] = a; });
  const PRE = {};
  ACTIONS.forEach((a) => { PRE[a.id] = a.keys.map((k) => ({ t: k.t, p: resolve(k.p) })); });

  // 载入用户自定义动作（此时 BY_ID / PRE 已就绪，才能注册进动作库）
  customs.forEach((a) => {
    if (a && a.id && Array.isArray(a.keys) && a.keys.length) { a.cat = 'custom'; registerAction(a); }
  });

  // 动作分类：无 cat 的 12 个是基础律动
  const ACT_CATS = { all: '全部', basic: '基础律动', star: '七彩星级', dance: '舞种律动', hand: '官方手位', comp: '比赛专业', custom: '自定义' };
  let actCat = 'all';
  function actionList() {
    if (actCat === 'all') return ACTIONS;
    if (actCat === 'basic') return ACTIONS.filter((a) => !a.cat || a.cat === 'basic');
    if (actCat === 'star') {
      const list = ACTIONS.filter((a) => a.cat === 'star');
      if (starLv === 'all') return list;
      if (starLv === 'kid') return list.filter((a) => /^s_kid/.test(a.id));
      return list.filter((a) => a.lv === starLv);
    }
    if (actCat === 'dance') {
      const list = ACTIONS.filter((a) => a.cat === 'dance');
      return danceSub === 'all' ? list : list.filter((a) => a.sub === danceSub);
    }
    return ACTIONS.filter((a) => a.cat === actCat);
  }

  function resolve(p) {
    const o = {};
    for (const k in BASE) o[k] = Array.isArray(BASE[k]) ? BASE[k].slice() : BASE[k];
    for (const k in p) o[k] = Array.isArray(p[k]) ? p[k].slice() : p[k];
    return o;
  }

  function lerpPose(a, b, w) {
    const o = {};
    for (const k in a) {
      const va = a[k], vb = b[k] === undefined ? a[k] : b[k];
      if (Array.isArray(va)) {
        o[k] = [lerp(va[0], vb[0], w), lerp(va[1], vb[1], w), lerp(va[2], vb[2], w)];
      } else {
        o[k] = lerp(va, vb, w);
      }
    }
    return o;
  }

  function sampleAction(actId, t) {
    let keys = PRE[actId];
    // 拆分出来的段（父id#k ofN）是按需生成的，第一次用到才建
    if (!keys) { materializeSeg(actId); keys = PRE[actId]; }
    keys = keys || PRE.bounce;
    t = clamp(t, 0, 1);
    let a = keys[0], b = keys[keys.length - 1];
    for (let i = 0; i < keys.length - 1; i++) {
      if (t >= keys[i].t && t <= keys[i + 1].t) { a = keys[i]; b = keys[i + 1]; break; }
    }
    const span = Math.max(1e-4, b.t - a.t);
    const w = smooth(clamp((t - a.t) / span, 0, 1));
    return lerpPose(a.p, b.p, w);
  }

